  "qcm": {
    "id": "atari-ch03-qcm",
    "seuil": 0.7,
    "questions": [
      { "id": "q1", "enonce": "Que fait \`MOVE.W (A0)+,D1\` ?", "choix": ["A0 avance de 2, puis lecture", "Lecture du mot pointé par A0, puis A0 avance de 2", "Lecture du mot pointé par A0 + 2"], "bonne": 1, "explication": "Postincrémentation : on lit d'abord, puis le pointeur avance de la taille de l'opérande." },
      { "id": "q2", "enonce": "Quelle instruction charge dans A0 l'adresse de TABLE, et non son contenu ?", "choix": ["MOVE.L TABLE,A0", "LEA TABLE,A0", "MOVE.L (TABLE),A0"], "bonne": 1, "explication": "\`LEA\` charge l'adresse effective ; \`MOVE.L TABLE,A0\` chargerait le mot long rangé à cette adresse." },
      { "id": "q3", "enonce": "\`MOVEQ\` accepte des valeurs de…", "choix": ["0 à 255", "−128 à 127", "1 à 8"], "bonne": 1, "explication": "MOVEQ charge un octet signé étendu sur 32 bits. Les valeurs 1 à 8, c'est ADDQ/SUBQ." },
      { "id": "q4", "enonce": "Après \`DIVU #10,D0\` avec D0 = 123, D0 vaut…", "choix": ["$0000000C", "$0003000C", "$000C0003"], "bonne": 1, "explication": "Quotient 12 ($C) dans le mot faible, reste 3 dans le mot fort." },
      { "id": "q5", "enonce": "Pour éteindre le bit 3 d'un octet sans toucher aux autres, on utilise…", "choix": ["OR.B #%00001000", "AND.B #%11110111", "EOR.B #%00001000"], "bonne": 1, "explication": "AND avec un masque où seul le bit visé est à 0." },
      { "id": "q6", "enonce": "Après \`BTST #2,D0\`, le flag Z vaut 1. Cela signifie que…", "choix": ["le bit 2 de D0 vaut 1", "le bit 2 de D0 vaut 0", "D0 vaut 0"], "bonne": 1, "explication": "BTST met dans Z l'inverse du bit testé." },
      { "id": "q7", "enonce": "Après ces deux lignes, lequel de ces branchements saute ?", "code": "@code.s#qcm-cmp", "choix": ["BGT", "BEQ", "BLT"], "bonne": 2, "explication": "CMP.W #9,D1 calcule D1 − 9 = 5 − 9 < 0 : « D1 est plus petit que 9 » en signé (BLT saute)." },
      { "id": "q8", "enonce": "Pour comparer deux nombres non signés, « plus grand que » s'écrit…", "choix": ["BGT", "BHI", "BPL"], "bonne": 1, "explication": "BHI/BCS/BCC/BLS sont les conditions non signées ; BGT/BLT/BGE/BLE les signées." },
      { "id": "q9", "enonce": "Combien de fois s'exécute \`ADDQ.W #1,D1\` ?", "code": "@code.s#qcm-dbra", "choix": ["4", "5", "6"], "bonne": 1, "explication": "DBRA fait N + 1 tours : 4 + 1 = 5." },
      { "id": "q10", "enonce": "Que fait \`BSR\` avant de sauter ?", "choix": ["Il sauvegarde tous les registres", "Il empile l'adresse de retour", "Rien, comme BRA"], "bonne": 1, "explication": "BSR empile l'adresse de l'instruction suivante ; RTS la dépilera." },
      { "id": "q11", "enonce": "Un sous-programme commence par \`MOVEM.L D1-D3,-(SP)\`. Que doit-il faire avant \`RTS\` ?", "choix": ["MOVEM.L (SP)+,D1-D3", "MOVEM.L D1-D3,(SP)+", "Rien de spécial"], "bonne": 0, "explication": "Il restaure les mêmes registres en dépilant, pour que l'adresse de retour revienne au sommet." },
      { "id": "q12", "enonce": "Pour multiplier rapidement D0.W par 4 (non signé), on peut écrire…", "choix": ["LSL.W #2,D0", "LSR.W #2,D0", "ROL.W #4,D0"], "bonne": 0, "explication": "Décaler de 2 bits à gauche multiplie par 2², soit 4." },
      { "id": "q13", "enonce": "Après \`MOVE.L #$AABBCCDD,$2000\`, que lit \`MOVE.W $2002,D0\` ?", "choix": ["$AABB", "$CCDD", "$DDCC"], "bonne": 1, "explication": "Le poids fort est à l'adresse la plus basse : $2000-$2001 contiennent $AABB, et $2002-$2003 contiennent $CCDD." },
      { "id": "q14", "enonce": "Après \`MOVE.L D0,-(SP)\`, SP a…", "choix": ["augmenté de 4", "diminué de 4", "gardé sa valeur"], "bonne": 1, "explication": "La pile descend : SP recule de 4 avant l'écriture du mot long." }
    ]
  },
